mapper.select:
SELECT tdm01_hr_id AS hr_id , tdm01_person_id AS person_id , tdm01_person_nm AS person_name , tdm01_pos_nm AS pos_name , tdm01_org_nm AS org_name , tdm01_hire_date AS hire_date , tdm01_retire_date AS retire_date , tdm01_end_date AS end_date , tdm01_upd_nm AS upd_name , tdm01_upd_date_str AS upd_date_str , tdm01_add_title AS add_title FROM ( SELECT * , COALESCE(TO_CHAR(tdm01_upd_date, 'yyyy-mm-dd HH24:MI:SS'), ''::text) AS tdm01_upd_date_str , CONCAT( ( SELECT '[사내]'||STRING_AGG(tdm03_add_title_nm, ', ') FROM tdm03_add_title WHERE tdm03_person_id = tdm01_person_id AND f_today() BETWEEN tdm03_start_date AND COALESCE(tdm03_close_date,'2999-12-31'::date) )||' ' , ( SELECT '[사외]'||f_get_tdmPersonInfo(tdm01_person_id, f_today(), '4') ) ) AS tdm01_add_title FROM ( SELECT * , f_cdnm('EmpPosCode' , tdm01_pos_cd , tdm01_company_id, f_today()) AS tdm01_pos_nm , f_cdnm('EmpTitleCode', tdm01_title_cd, tdm01_company_id, f_today()) AS tdm01_title_nm FROM tdm01_hr WHERE tdm01_company_id = #{companyId}
AND COALESCE(tdm01_retire_date,'9999-12-31'::date) > f_today()
) t WHERE 1=1 AND CONCAT(tdm01_person_nm, tdm01_pos_nm, tdm01_org_nm) ILIKE #{searchText} ) r ORDER BY tdm01_pos_cd, tdm01_person_nm COLLATE "ko_KR.utf8"

mapper.insert:
INSERT INTO tdm01_hr
       ( tdm01_hr_id, tdm01_company_id, tdm01_person_id, tdm01_person_nm, tdm01_person_no
       , tdm01_pos_cd, tdm01_title_cd, tdm01_hire_date, tdm01_retire_date, tdm01_end_date
       , tdm01_org_id, tdm01_org_nm, tdm01_org_head_nm, tdm01_upd_nm, tdm01_upd_date )
SELECT f_create_seq()
     , #{companyId}
     , #{now.personId}
     , #{now.korName}
     , #{now.empNo}
     , #{now.posCode}
     , #{now.titleCode}
     , #{now.hireDate}
     , #{now.retireDate}
     , NULL
     , #{now.orgCodeId}
     , #{now.orgCodeName}
     , #{now.orgHeadName}
     , #{updName}
     , f_sysdate()

mapper.update:
UPDATE tdm01_hr
   SET tdm01_person_nm   = #{hr.personName}
     , tdm01_pos_cd      = #{hr.posCode}
     , tdm01_title_cd    = #{hr.titleCode}
     , tdm01_hire_date   = #{hr.hireDate}
     , tdm01_retire_date = #{hr.retireDate}
     , tdm01_end_date    = #{hr.endDate}
     , tdm01_org_id      = #{hr.orgId}
     , tdm01_org_nm      = #{hr.orgName}
     , tdm01_org_head_nm = #{orgHeadName}
     , tdm01_upd_nm      = #{updName}
     , tdm01_upd_date    = f_sysdate()
 WHERE tdm01_person_id = #{hr.personId}

UPDATE tdm01_hr
   SET tdm01_retire_date = #{retireDate}
     , tdm01_end_date    = #{endDate}
     , tdm01_upd_nm      = #{updName}
     , tdm01_upd_date    = f_sysdate()
 WHERE tdm01_person_id = #{personId}

mapper.insert:
INSERT INTO tdm02_hr_record
       ( tdm02_hr_record_id, tdm02_company_id, tdm02_reg_date, tdm02_reg_type, tdm02_person_nm
       , tdm02_change_data, tdm02_init_nm, tdm02_init_date, tdm02_note, tdm02_apply_cd
       , tdm02_upd_nm, tdm02_upd_date )
SELECT f_create_seq()
     , #{companyId}
     , f_today()
     , #{regType}
     , #{personName}
     , #{changeData}
     , #{updName}
     , f_sysdate()
     , NULL
     , '0'
     , #{updName}
     , f_sysdate()
